.ds-job {
  position: relative;
  display: block;
  width: 100%;
  border-radius: 28px;
  padding: 20px;
  text-align: left;
  background: linear-gradient(180deg, rgba(255, 255, 255, .055), rgba(255, 255, 255, .02)), #141416;
  box-shadow: 0 0 0 1px rgba(255, 255, 255, .10) inset, 0 1px 0 rgba(255, 255, 255, .06) inset;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", system-ui, sans-serif;
  color: #f5f5f7;
