.ds-job-row { display: flex; align-items: center; gap: 10px; }
.ds-job h2 { margin: 0; flex: 1; font-size: 1.65rem; line-height: 1.2; letter-spacing: -.03em; font-weight: 700; }
.ds-min { margin-left: auto; color: rgba(235, 235, 245, .48); font-size: 13px; font-variant-numeric: tabular-nums; }
.ds-sub { color: rgba(235, 235, 245, .72); font-size: .88rem; line-height: 1.35; margin: 4px 0 0; }
.ds-meta { color: rgba(235, 235, 245, .48); font-size: 13px; line-height: 1.35; margin: 0; }
.ds-live {
  width: 8px; height: 8px; border-radius: 50%; background: #30d158; flex: 0 0 auto;
  box-shadow: 0 0 0 0 rgba(48, 209, 88, .55);
  animation: ds-pulse 1.8s ease-out infinite;
}
.ds-rail { display: grid; grid-template-columns: repeat(7, 1fr); gap: 4px; height: 6px; margin: 14px 0 10px; }
.ds-rail i { border-radius: 3px; background: rgba(255, 255, 255, .14); position: relative; overflow: hidden; }
.ds-rail i.done { background: #f5f5f7; }
.ds-rail i.now::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, .95), transparent);
  transform: translateX(-100%);
  animation: ds-sweep 1.6s linear infinite;
}
@keyframes ds-pulse {
  70% { box-shadow: 0 0 0 8px rgba(48, 209, 88, 0); }
  100% { box-shadow: 0 0 0 0 rgba(48, 209, 88, 0); }
}
@keyframes ds-sweep { to { transform: translateX(100%); } }
@media (prefers-reduced-motion: reduce) {
  .ds-live, .ds-rail i.now::after { animation: none; }
}

